    [Fact]
    public void Definitions_are_locked_in_order_with_scope_description_example_digest_and_canonical_schema()
    {
        var actual = AgentToolDefinitionCatalog.Get()
            .Select(definition => new DefinitionLock(
                definition.ToolId,
                definition.ToolVersion,
                definition.Scope,
                Sha256(definition.Description),
                definition.ExampleArguments is null ? null : Sha256(AgentToolDefinitionCatalog.CanonicalSchemaJson(definition.ExampleArguments)),
                AgentToolDefinitionCatalog.ComputeSchemaDigest(definition.InputSchema),
                AgentToolDefinitionCatalog.CanonicalSchemaJson(definition.InputSchema)))
            .ToArray();

        Assert.Equal(DefinitionLocks, actual);
    }

    [Fact]
    public void Catalog_version_and_model_tool_capacity_are_locked()
    {
        Assert.Equal("1.0.0", AgentToolDefinitionCatalog.CurrentVersion);
        Assert.Equal(32, AgentToolDefinitionCatalog.MaximumModelTools);
    }

    private static string Sha256(string text) =>
        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
}
